pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Progress of the stream
    let progress = step_index as f64 / total_items as f64;

    // ------------------------------------------------------------------
    // Base score = remaining space after placement
    let mut score = post_residual as f64;

    // ------------------------------------------------------------------
    // Residual deviation penalty
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += 0.35 * residual_diff;
    if mean_residual < 2.5 {
        score += 0.25 * residual_diff;
    }

    // ------------------------------------------------------------------
    // Look‑ahead for the next item
    if next_item_size > 0 && post_residual < next_item_size {
        score += 1.4 * (next_item_size - post_residual) as f64;
    }

    // ------------------------------------------------------------------
    // Penalty for many open bins
    score += 0.06 * (open_bins_count as f64).powf(0.8);
    if progress > 0.92 && open_bins_count > 4 {
        score += 0.04 * (open_bins_count as f64 - 4.0);
    }

    // ------------------------------------------------------------------
    // New‑bin candidate adjustment
    if bin_residual == bin_capacity {
        let base_penalty = if fitting_bins_count >= 3 {
            18.0
        } else if fitting_bins_count >= 1 {
            10.0
        } else {
            14.0
        };

        if item_size as f64 > 0.8 * bin_capacity as f64 {
            score -= 5.0;
        } else {
            let cap_factor = (bin_capacity as f64).max(1.0) / 120.0;
            score += base_penalty * (1.0 - progress).max(0.0) * cap_factor;
        }
    }

    // ------------------------------------------------------------------
    // Reward for a unique fitting bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // ------------------------------------------------------------------
    // Residual ratio checks
    let residual_ratio = post_residual as f64 / bin_capacity as f64;
    if residual_ratio > 0.65 {
        score += 2.2 * (residual_ratio - 0.65);
    }

    let mean_ratio = mean_residual / bin_capacity as f64;
    if mean_residual < 6.0 && residual_ratio > mean_ratio {
        score += 1.2 * (residual_ratio - mean_ratio);
    }

    // ------------------------------------------------------------------
    // Tight‑fit reward
    let remaining_after = bin_residual - item_size;
    if remaining_after <= 2 {
        score -= 5.0;
    }

    // ------------------------------------------------------------------
    // Extra look‑ahead penalty when the gap is too big for the next item
    if next_item_size > 0
        && (next_item_size as f64 > 0.7 * bin_capacity as f64)
        && remaining_after > next_item_size
    {
        score += 1.0 * (remaining_after - next_item_size) as f64;
    }

    // ------------------------------------------------------------------
    // Occupancy penalty when many bins are open
    let occupancy_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if open_bins_count > 3 && occupancy_ratio < 0.55 {
        score += 0.7 * (0.55 - occupancy_ratio);
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Fraction of the stream processed
    let progress = step_index as f64 / total_items as f64;

    // Residual after placement as a fraction of the bin capacity
    let waste_ratio = post_residual as f64 / bin_capacity as f64;

    // ---------- Core waste penalty ----------
    // Base penalty grows with waste but is relaxed early in the stream
    let mut score = waste_ratio * 10.0 * (0.85 + 0.15 * progress);

    // ---------- Residual vs item size ----------
    if post_residual <= item_size / 2 {
        // Very tight fit – reward cubic proximity to zero
        let rel = post_residual as f64 / (item_size as f64 / 2.0);
        score -= 4.0 * (1.0 - rel).powi(3);
    } else if post_residual <= item_size {
        // Acceptable tightness – quadratic reward
        let rel = post_residual as f64 / item_size as f64;
        score -= 2.5 * (1.0 - rel).powi(2);
    } else {
        // Excess leftover – sqrt penalty
        let excess = (post_residual - item_size) as f64;
        score += 1.5 * excess.sqrt();
    }

    // ---------- Deviation from global mean residual ----------
    let mean_diff = post_residual as f64 - mean_residual;
    score += 0.3 * mean_diff * mean_diff;

    // ---------- Look‑ahead penalty ----------
    if next_item_size > 0 {
        let gap = (next_item_size as i32 - post_residual as i32) as f64;
        if gap > 0.0 {
            score += 2.0 * gap * gap * (1.0 - progress).powi(2);
        }
    }

    // ---------- Open‑bin reuse incentive ----------
    if open_bins_count > 6 {
        let factor = (open_bins_count as f64 - 6.0).powf(1.3);
        score += 0.02 * factor * (0.9 + 0.1 * progress);
    }

    // ---------- New‑bin candidate handling ----------
    if bin_residual == bin_capacity {
        let base = if fitting_bins_count > 0 { 8.0 } else { 3.5 };
        // Slightly harsher penalty when many open bins exist
        let open_factor = 1.0 + (open_bins_count as f64) * 0.05;
        score += base * (1.0 - progress).powf(1.6) * open_factor;
    }

    // ---------- Unique fitting bin reward ----------
    if fitting_bins_count == 1 {
        score -= 7.0;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Fraction of stream processed
    let progress = step_index as f64 / total_items as f64;

    // Waste ratio: leftover after placing the item relative to bin capacity
    let waste_ratio = post_residual as f64 / bin_capacity as f64;

    // ---------- Base waste penalty ----------
    // Use a slightly steeper penalty that adapts to progress
    let mut score = waste_ratio * 10.0 * (0.7 + 0.3 * progress);

    // Extra penalty for large waste
    if waste_ratio > 0.5 {
        score += 4.0 * (waste_ratio - 0.5).powi(2);
    }

    // ---------- Residual vs item size ----------
    if item_size > 0 {
        let ratio = post_residual as f64 / (item_size as f64 + 1.0);
        if ratio <= 1.0 {
            // Tight fit: reward with a quartic curve that peaks at ratio=0
            let rel = 1.0 - ratio;
            score -= 4.0 * rel.powi(4);
        } else {
            // Over‑fill (shouldn't happen in normal packing but keep safe)
            let excess = (post_residual - item_size) as f64;
            score += 1.2 * excess.sqrt();
        }
    }

    // ---------- Deviation from global mean residual ----------
    let mean_diff = post_residual as f64 - mean_residual;
    score += 0.2 * mean_diff * mean_diff;

    // ---------- Look‑ahead penalty / reward ----------
    if next_item_size > 0 {
        let diff_next = next_item_size as i32 - post_residual as i32;
        if diff_next > 0 {
            // Leftover smaller than next item – penalty grows quadratically
            let gap = diff_next as f64;
            score += 2.5 * gap * gap * (1.0 - progress).powi(2);
        } else {
            // Leftover larger than next item – reward for tightness
            let over = (-diff_next) as f64;
            score -= 0.9 * over * over * progress.powi(2);
        }
    }

    // ---------- Open‑bin reuse incentive ----------
    if open_bins_count > 3 {
        let factor = (open_bins_count as f64 - 3.0).powf(1.1);
        score += 0.02 * factor * (0.8 + 0.2 * progress);
    }

    // ---------- New‑bin candidate handling ----------
    if bin_residual == bin_capacity {
        let base = if fitting_bins_count > 0 { 5.0 } else { 2.5 };
        let open_factor = 1.0 + 0.03 * open_bins_count as f64;
        score += base * (1.0 - progress).powf(1.3) * open_factor;
    }

    // ---------- Unique fitting bin reward ----------
    if fitting_bins_count == 1 {
        score -= 6.0;
    }

    // ---------- Residual closeness to mean reward ----------
    if (post_residual as f64 - mean_residual).abs() <= 0.05 * mean_residual {
        score -= 0.3;
    }

    // ---------- Small residual reward ----------
    // Favor bins that leave very little space (except when waste is too high)
    if waste_ratio < 0.1 {
        score -= 1.5 * (0.1 - waste_ratio);
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Stream progress [0.0, 1.0]
    let progress = step_index as f64 / total_items as f64;

    // Waste ratio and residual fraction
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    let residual_frac = waste_ratio;

    // Base penalty driven by waste
    let mut score = waste_ratio * 4.5 * (0.6 + 0.4 * progress);

    // Small residual reward / excess penalty
    if post_residual <= item_size {
        let rel = post_residual as f64 / item_size as f64;
        score -= 3.8 * (1.0 - rel).powi(2);
    } else {
        let excess = (post_residual - item_size) as f64;
        // Exponential penalty for large excess
        score += 0.8 * (excess / item_size as f64).powi(2);
    }

    // Deviation from global mean residual
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += 0.2 * mean_diff * (1.0 - progress);

    // Look‑ahead handling
    if next_item_size > 0 {
        let gap = next_item_size as i32 - post_residual as i32;
        if gap > 0 {
            // Cannot fit next item – heavy penalty easing with progress
            score += 1.0 * (gap as f64).powi(2) * (1.0 - progress);
        } else if gap < 0 {
            let over = -(gap as f64);
            if over <= next_item_size as f64 * 0.05 {
                score -= 0.6 * over.powi(2);
            } else {
                score += 0.3 * over.powi(2);
            }
        }

        // Synergy when residual almost matches next item
        let ratio = post_residual as f64 / next_item_size as f64;
        if ratio > 0.95 && ratio < 1.05 {
            score -= 0.4;
        }

        // Extra bonus if residual is very close to next item size
        let diff = (post_residual as i32 - next_item_size as i32).abs();
        if diff <= 5 {
            score += 0.2;
        }
    }

    // Penalise excessive open bins early in the stream
    if open_bins_count > 6 {
        score += 0.05 * open_bins_count as f64 * (1.0 - 0.5 * progress);
    }

    // New‑bin candidate handling
    if bin_residual == bin_capacity {
        let base_penalty = if fitting_bins_count > 0 { 6.0 } else { 8.0 };
        score += base_penalty * (1.0 - progress).powf(1.2);
    }

    // Reward a unique fitting bin
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Reward if residual after placement is close to the next item
    if next_item_size > 0 && bin_residual >= next_item_size {
        let diff = bin_residual as i32 - next_item_size as i32;
        if diff <= (item_size as i32 / 5) {
            score -= 1.0;
        }
    }

    // Fine‑grained residual fitting
    if residual_frac < 0.01 {
        score -= 0.9;
    } else if residual_frac > 0.35 {
        score += 0.4;
    }

    // Penalise fragmentation when many fitting bins exist
    if fitting_bins_count > 4 {
        score += 0.3 * ((fitting_bins_count as f64) - 4.0) * (1.0 - progress);
    }

    // Extra penalty for very high waste ratio
    if waste_ratio > 0.75 {
        score += 1.0;
    }

    // Penalty if mean residual grows too large relative to capacity
    if mean_residual > (bin_capacity as f64 * 0.4) {
        score += 0.2 * (mean_residual - bin_capacity as f64 * 0.4) / (bin_capacity as f64 * 0.4);
    }

    score
}

pub fn score_bin(
