    let progress = step_index as f64 / total_items as f64;

    // Basic waste metrics
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    let residual_frac = waste_ratio;

    // Base penalty grows with waste, tempered by progress
    let mut score = waste_ratio * 5.0 * (0.7 + 0.3 * progress);

    // Reward small residuals relative to the item
    if post_residual <= item_size {
        let rel = post_residual as f64 / item_size as f64;
        score -= 4.0 * (1.0 - rel).powi(2);
    } else {
        // Excess residual: moderate penalty
        let excess = (post_residual - item_size) as f64;
        score += 1.2 * excess.sqrt();
    }

    // Deviation from the global mean residual
    let mean_diff = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * mean_diff * (1.0 - progress);

    // Look‑ahead penalty / reward
    if next_item_size > 0 {
        let gap = next_item_size as i32 - post_residual as i32;
        if gap > 0 {
            // Cannot fit next item: heavy penalty that eases with progress
            score += 1.5 * (gap as f64).powi(2) * (1.0 - progress);
        } else if gap < 0 {
            // Residual is just enough for next item: small bonus if over is tiny
            let over = -(gap as f64);
            if over <= (next_item_size as f64 * 0.1) {
                score -= 0.5 * over.powi(2);
            } else {
                score += 0.2 * over.powi(2);
            }
        }

        // Extra synergy: residual almost matches next item size
        let ratio = post_residual as f64 / next_item_size as f64;
        if ratio > 1.0 && ratio < 1.2 {
            score -= 0.3;
        }
    }

    // Penalise too many open bins
    if open_bins_count > 4 {
        score += 0.04 * open_bins_count as f64 * (1.0 - 0.4 * progress);
    }

    // New‑bin candidate handling
    if bin_residual == bin_capacity {
        let base_penalty = if fitting_bins_count > 0 { 5.0 } else { 7.0 };
        score += base_penalty * (1.0 - progress).powf(1.1);
    }

    // Reward a unique fitting bin
    if fitting_bins_count == 1 {
        score -= 4.5;
    }

    // Extra reward if residual after placement is close to the next item size
    if next_item_size > 0 && bin_residual >= next_item_size {
        let diff = bin_residual as i32 - next_item_size as i32;
        if diff <= (item_size as i32 / 6) {
            score -= 0.8;
        }
    }

    // Fine‑grained residual fitting
    if residual_frac < 0.015 {
        score -= 0.7;
    } else if residual_frac > 0.4 {
        score += 0.5;
    }

    // Penalise many fitting bins to discourage fragmentation
    if fitting_bins_count > 3 {
        score += 0.25 * ((fitting_bins_count as f64) - 3.0) * (1.0 - progress);
    }

    // Extra penalty for very high waste ratio
    if waste_ratio > 0.8 {
        score += 1.2;
    }

    score
}

pub fn score_bin(
    item_size: u32,
    bin_residual: u32,
    bin_capacity: u32,
    step_index: usize,
    total_items: usize,
    open_bins_count: usize,
    mean_residual: f64,
    next_item_size: u32,
    post_residual: u32,
    fitting_bins_count: usize,
) -> f64 {
    // Fraction of the stream processed
    let progress = step_index as f64 / total_items as f64;

    // Residual after placement as a fraction of the bin capacity
    let waste_ratio = post_residual as f64 / bin_capacity as f64;

    // ---------- Base waste penalty ----------
    let mut score = waste_ratio * 8.0 * (0.8 + 0.2 * progress);

    // ---------- Residual vs item size ----------
    if item_size > 0 {
        let quarter = item_size / 4;
        if post_residual <= quarter && quarter > 0 {
            let rel = post_residual as f64 / quarter as f64;
            score -= 5.0 * (1.0 - rel).powi(4);
        } else if post_residual <= item_size {
            let rel = post_residual as f64 / item_size as f64;
            score -= 3.0 * (1.0 - rel).powi(3);
        } else {
            let excess = (post_residual - item_size) as f64;
            score += 1.3 * excess.sqrt();
        }
    }

    // ---------- Deviation from global mean residual ----------
    let mean_diff = post_residual as f64 - mean_residual;
    score += 0.25 * mean_diff * mean_diff;

    // ---------- Look‑ahead penalty / reward ----------
    if next_item_size > 0 {
        let diff_next = next_item_size as i32 - post_residual as i32;
        if diff_next > 0 {
            // leftover smaller than next item – penalty grows as gap widens
            let gap = diff_next as f64;
            score += 2.2 * gap * gap * (1.0 - progress).powi(2);
        } else {
            // leftover greater than next item – slight reward for tighter fit
            let over = (-diff_next) as f64;
            score -= 0.8 * over * over * progress.powi(2);
        }
    }

    // ---------- Open‑bin reuse incentive ----------
    if open_bins_count > 5 {
        let factor = (open_bins_count as f64 - 5.0).powf(1.2);
        score += 0.015 * factor * (0.85 + 0.15 * progress);
    }

    // ---------- New‑bin candidate handling ----------
    if bin_residual == bin_capacity {
        let base = if fitting_bins_count > 0 { 6.0 } else { 3.0 };
        let open_factor = 1.0 + 0.04 * open_bins_count as f64;
        score += base * (1.0 - progress).powf(1.4) * open_factor;
    }

    // ---------- Unique fitting bin reward ----------
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // ---------- Residual closeness to mean reward ----------
    if (post_residual as f64 - mean_residual).abs() <= 0.05 * mean_residual {
        score -= 0.5;
    }

    score
}
